INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`) VALUES
(39131, 'ruRU', 'Во владении силой', 'Найдите тех, кто может рассказать о происхождении осколка.', 'Отзвуки тысячи миров кружатся на твоей ладони. Его истинная ценность — в глазах смотрящего.'),
(39388, 'ruRU', 'Мудрость Лунного Когтя', 'Встретьтесь с Таоном Лунным Когтем в его логове.', 'Наши быстрые действия сегодня остановили эту агрессию и спасли мою долину. Как ты и просил, я присоединюсь к Малфуриону в Роще Кенария.$B$BИ всё же есть многое об этих сатирах, что я хочу рассказать тебе. Эти сведения будут для тебя весьма ценны.$B$BПожалуйста, встретимся в моём логове перед отправлением.'),
(39424, 'ruRU', 'Всё подряд!', '', ''),
(39462, 'ruRU', 'Первобытное возмездие', '', ''),
(39838, 'ruRU', 'Пожар!', 'Используйте вёдра с водой Камиллы Кляйстер, чтобы потушить пожар.', 'Эй, ты! Искатель приключений! Помоги нам! Повозка загорелась!'),
(39845, 'ruRU', 'Кузница обраума', 'Завершите строительство Кузницы обраума в Даларане.', 'Компоненты кузницы собраны, и, как я понимаю, архимаг Карлейн подыскал для нас место, чтобы начать строительство: на поверхности, рядом с кузнецом.$b$bЗаходи в гости как-нибудь, $n.'),
(39869, 'ruRU', 'Плата за душу', 'Победите Хелию и освободите валарьяров.', '[PH] Как и было предсказано, ты прибыл... Хелия глупа, если думает, что я позволю ей переправить меня в Хельхейм. Один уже улыбнулся мне, моя душа принадлежит Валхалле.\n\nНе ошибись, я не пленник. Перед моей смертью Один явился мне в облике ворона. Он восхвалил мои битвы в жизни и дал мне задание, от которого ни один врайкул не смог бы отказаться. Прибыли хеларьяры... и я позволил им убить меня.\n\nПленник? Нет, я освободитель, посланный Одином, чтобы освободить души валарьяров.'),
(39962, 'ruRU', 'Беда для Окуны', 'Найдите Окуну Длинного Бивня.', '<Вы открываете бутылку и находите внутри послание.>\n\nПомогите! Мне нужен кто-то... но не кто угодно. Мне нужен защитник! Я наконец вырвалась из хватки принца Океанус, но теперь меня преследует его отец, король Глубокобородый.\n\nЯ наслаждалась свободой и решила пойти на рыбалку, когда этот гигант напал на меня. С тех пор я бегаю по этим островам, пытаясь избежать этого существа... если кто-нибудь получит это сообщение, пожалуйста, пришлите помощь!'),
(40121, 'ruRU', 'Влияние лей-линий', '', ''),
(40160, 'ruRU', 'Волшебные моллюски', 'Соберите заряженных моллюсков у мурлоков из племени Хребет Ясновидения на Мурлочьей отмели.', '<Моллюск резонирует с чародейской энергией.>$B$BЧто мурлоки делают с чародейскими моллюсками?$B$BВозможно, твои союзники-помраченные найдут им применение.');
